static pair<double, double> CCT_to_xy_CIE_D(double CCT)
{
    double xD;
    if (CCT <= 7000.0)
    {
        xD = -4.607e9  / (CCT * CCT * CCT)
           +  2.9678e6 / (CCT * CCT)
           +  0.09911e3 / CCT
           +  0.244063;
    }
    else
    {
        xD = -2.0064e9 / (CCT * CCT * CCT)
           +  1.9018e6 / (CCT * CCT)
           +  0.24748e3 / CCT
           +  0.23704;
    }

    const double yD = -3.000 * xD * xD + 2.870 * xD - 0.275;

    return {xD, yD};
}

VisData getSpd(double CCT)
{
    const auto [xD, yD] = CCT_to_xy_CIE_D(CCT);

    const double denom = 0.0241 + 0.2562 * xD - 0.7341 * yD;

    const double M1 = (-1.3515 - 1.7703 * xD + 5.9114 * yD) / denom;
    const double M2 = ( 0.0300 - 31.4424 * xD + 30.0717 * yD) / denom;

    return views::iota(0, g_limitedVisSize) | views::transform([M1, M2](int i) {
        return max(0.0, S0[i] + M1 * S1[i] + M2 * S2[i]);
    }) | ranges::to<VisData>();
}

